test('Managed stop and shutdown cancel capture transition resume without modifying ordinary status', async t => {
  const {env,run}=await fixture(t);
  const stateDir=path.join(env.STM_DATA_DIR,'runtime/capture-transition');
  await fs.mkdir(stateDir,{recursive:true,mode:0o700});
  const marker=path.join(stateDir,'manual-stop.json');
  assert.equal(run('stop','stm').status,0);
  const first=await fs.readFile(marker,'utf8');assert.ok(JSON.parse(first).at>0);
  assert.equal(run('status').status,0);assert.equal(await fs.readFile(marker,'utf8'),first);
  assert.equal(run('shutdown').status,0);assert.ok(JSON.parse(await fs.readFile(marker,'utf8')).at>=JSON.parse(first).at);
});

