async function failedServer(env, prelude = '') {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['-e', prelude + 'require("./server/dist/index.js")'], {
      cwd: root, env: { ...process.env, HOST: '127.0.0.1', HTTP_ACCESS_LOG: '0', STM_DIAGNOSTIC_LOG: '0', STM_CONFIG_FILE: '', STM_PLAYBACK_STATE_FILE: '', ...env },
      stdio: ['ignore', 'pipe', 'pipe']
    });
    let stdout = '', stderr = '';
    const timeout = setTimeout(() => { child.kill('SIGKILL'); reject(new Error('Startup failure did not exit: ' + stderr)); }, 10000);
    child.stdout.on('data', bytes => stdout += bytes);
    child.stderr.on('data', bytes => stderr += bytes);
    child.on('error', reject);
    child.on('close', code => { clearTimeout(timeout); resolve({ code, stdout, stderr, records: stderr.split('\n').flatMap(line => { try { return [JSON.parse(line)]; } catch { return []; } }) }); });
  });
}
test('State preparation is repeatable and preserves existing contents, owner and mode', async t => {
  const dir = await directory(t), state = path.join(dir, 'nested', 'state');
  await prepareStateDirectory(state);
  await fs.chmod(state, 0o750);
  await fs.writeFile(path.join(state, 'keep.json'), 'keep');
  const before = await fs.stat(state);
  await prepareStateDirectory(state);
  const after = await fs.stat(state);
  assert.equal(after.mode, before.mode); assert.equal(after.uid, before.uid); assert.equal(after.gid, before.gid);
  assert.deepEqual(await fs.readdir(state), ['keep.json']);
  assert.equal(await fs.readFile(path.join(state, 'keep.json'), 'utf8'), 'keep');
});
test('Invalid state paths fail before listening and log context with access logging off', async t => {
  const dir = await directory(t), file = path.join(dir, 'not-a-directory');
  await fs.writeFile(file, 'keep');
  const result = await failedServer({ STM_FE_STATE_DIR: file });
  assert.equal(result.code, 1); assert.equal(result.stdout, '');
  const error = result.records.find(record => record.operation === 'create_state_directory');
  assert.ok(error, result.stderr); assert.equal(error.path, file); assert.equal(error.code, 'EEXIST');
  assert.equal(error.process, 'frontend'); assert.equal(error.level, 'error'); assert.ok(error.time && error.pid && error.message);
  assert.equal(await fs.readFile(file, 'utf8'), 'keep');
});
test('Configuration initialization errors also pass through the startup error boundary', async () => {
  const result = await failedServer({ STM_FE_STATE_DIR: ' ' });
  assert.equal(result.code, 1);
  assert.ok(result.records.some(record => record.operation === 'startup' && record.message.includes('frontend state')), result.stderr);
});
test('A busy port logs the listening address and exits instead of remaining alive', async t => {
  const dir = await directory(t), portProbe = http.createServer();
  await new Promise(resolve => portProbe.listen(0, '127.0.0.1', resolve));
  t.after(() => new Promise(resolve => portProbe.close(resolve)));
  const port = portProbe.address().port;
  const result = await failedServer({ STM_FE_STATE_DIR: path.join(dir, 'fe'), LOG_DIR: dir, PORT: String(port) });
  assert.equal(result.code, 1);
  const error = result.records.find(record => record.code === 'EADDRINUSE');
  assert.ok(error, result.stderr); assert.equal(error.operation, 'listen'); assert.equal(error.host, '127.0.0.1'); assert.equal(error.port, port);
});
test('Write permission failures fail at startup and remain visible in stderr', async t => {
  const dir = await directory(t), state = path.join(dir, 'fe');
  await fs.chmod(dir, 0o755); await fs.mkdir(state, { mode: 0o555 });
  const result = await failedServer({ STM_FE_STATE_DIR: state }, process.getuid?.() === 0 ? 'process.setgid(65534);process.setuid(65534);' : '');
  assert.equal(result.code, 1);
  const error = result.records.find(record => record.code === 'EACCES');
  assert.ok(error, result.stderr); assert.equal(error.path, state); assert.equal(error.operation, 'check_state_directory_write');
  assert.deepEqual(await fs.readdir(state), []);
});
# stm

監視データの保持時間・全体容量上限・Time travelの保存境界は[docs/storage-retention.md](docs/storage-retention.md)を参照してください。

本番コンテナの構成、起動、権限、永続化は[docs/deployment.md](docs/deployment.md)を参照してください。

BE診断ログの形式・動的デバッグレベル・日次／サイズ退避・日数／合計容量保持は[docs/process-logging.md](docs/process-logging.md)を参照してください。Compose起動前にログ保存用のホストディレクトリ（既定`/srv/stm/logs`）を準備します。

障害調査用のログ・解析データ収集は`./scripts/stm-collect-logs`。設定とSupervisorの出力先から検出し、カレントディレクトリへ日時入りの`stm-logs-*.tar.gz`を保存します。capture配下は標準では除外し、`--include-capture`で含めます。[利用方法と収集範囲](docs/process-logging.md#診断ログの一括収集)を確認してください。

Supervisor配下のCPU・メモリ・ディスクI/Oの継続記録は[docs/process-stats.md](docs/process-stats.md)を参照してください。5秒間隔のJSON Linesを専用ログへ保存し、PID変更と子孫プロセスに追従します。

## Capture Health

`stm_healthd` は、capture hostのNIC、kernel receive path、dumpcap状態、PCAP処理待ち行列を1秒周期で収集します。STM本体とは別プロセスで、同じLinux network namespaceで動かしてください。

```sh
be/build/stm_healthd --config be/src/conf/stm_config.json
```

同じ設定ファイルで`dumpcap_runner`を起動すると、`capture_health.capture_status_file`へdumpcapの生存・設定状態を出力します。dumpcapの`-S`は統計表示専用でキャプチャと両立しないため、この状態ファイルでは生存・終了理由と設定値を扱い、ドロップ数は`null`です。`stm`は`pipeline_status_file`へPCAP watcherの未処理数と最古待機時間を出力します。FE serverは、`logs.dir/capture-health/live.ndjson`
