const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const root = path.resolve(__dirname, '../..');

async function fixture(t, running = true) {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'stm-supervisor-startup-'));
  t.after(() => fs.rm(dir, { recursive: true, force: true }));
  const bin = path.join(dir, 'bin'); await fs.mkdir(bin);
  const config = path.join(dir, 'supervisor.conf'); await fs.writeFile(config, '# mock');
  const env = { ...process.env, PATH: bin + ':' + process.env.PATH,
    STM_DATA_DIR: path.join(dir, 'data'), STM_LOG_DIR: path.join(dir, 'logs'),
    STM_LOG_LEVEL_FILE: path.join(dir, 'runtime', 'log-levels.json'),
    STM_CONFIG_DIR: path.join(dir, 'conf'), STM_FRONTEND_USER: 'root',
    STM_DEFAULT_CONFIG_DIR: path.join(dir, 'defaults'), SUPERVISOR_CONFIG: config,
    MOCK_READY: path.join(dir, 'ready'), MOCK_CALLS: path.join(dir, 'calls'), MOCK_FAIL: '' };
  if (running) await fs.writeFile(env.MOCK_READY, 'ready');
  const scripts = {
    supervisorctl: `#!/bin/sh
printf 'ctl %s\\n' "$*" >> "$MOCK_CALLS"
shift 2
case "$1" in
  pid) [ -f "$MOCK_READY" ] ;;
  status|stop) [ -f "$MOCK_READY" ] ;;
  *) if [ "$MOCK_FAIL" = control ]; then echo 'mock control failure' >&2; exit 7; fi ;;
esac
`,
    supervisord: `#!/bin/sh
printf 'daemon %s\\n' "$*" >> "$MOCK_CALLS"
if [ "$MOCK_FAIL" = daemon ]; then echo 'mock daemon startup failure' >&2; exit 9; fi
touch "$MOCK_READY"
`,
    chown: '#!/bin/sh\nexit 0\n'
  };
  for (const [name, script] of Object.entries(scripts)) await fs.writeFile(path.join(bin, name), script, { mode: 0o755 });
  const run = (...args) => spawnSync('/bin/sh', [path.join(root, 'scripts/stm-supervisor'), ...args], { env, encoding: 'utf8', timeout: 10000 });
  const entrypoint = (...args) => spawnSync('/bin/sh', [path.join(root, 'docker/entrypoint.sh'), ...args], { env, encoding: 'utf8', timeout: 10000 });
  return { dir, env, run, entrypoint };
}
