const net = require('node:net');
const { spawn } = require('node:child_process');
const WebSocket = require('../node_modules/ws');
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function fixture(t, enabled) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'stm-diagnostics-api-'));
  const config = path.join(root, 'stm.json');
  await fs.writeFile(config, JSON.stringify({ capture_health: { pipeline_progress_file: 'capture-health/pipeline-progress.ndjson', diagnostics: { enabled } } }));
  await fs.mkdir(path.join(root, 'capture-health'));
  const now = Date.now() / 1000;
  const processingTiming = { interval_sec: 1, current_stage: 'analysis', current_stage_elapsed_ms: 12, stages: {} };
  for (const name of ['tsv_read', 'analysis', 'aggregation', 'journal']) processingTiming.stages[name] = { total_ms: 10, ms_per_sec: 10, count: 2, mean_ms: 5, max_ms: 7 };
  await fs.writeFile(path.join(root, 'capture-health/live.ndjson'), JSON.stringify({ schema_version: 1, record_type: 'capture_health', observed_at: now, host: { id: 'fixture' }, overall: { state: 'ok', reasons: [] }, interfaces: [], kernel: {}, media_network: {},
    pipeline: { progress_observed_at: now, processing_timing: processingTiming, end_to_end_lag_sec: 12, tshark_output_packets_per_sec: 50, processed_packets_per_sec: 40, diagnostics: { unread_files: 10, ring_remaining_sec: 48 } } }) + '\n');
  const statsFile = path.join(root, 'capture-health/process-stats.json');
  await fs.writeFile(statsFile, JSON.stringify({ schema_version: 1, observed_at: now, interval_sec: 1, processes: [{ timestamp: new Date().toISOString(), boot_id: 'boot', pid: 42, start_ticks: 100, command: 'tshark', program: 'stm', cpu_pct: 99, rss_bytes: 1024 * 1024, interval_sec: 1 }] }));
  const probe = net.createServer(); await new Promise(resolve => probe.listen(0, '127.0.0.1', resolve));
  const port = probe.address().port; await new Promise(resolve => probe.close(resolve));
  const child = spawn(process.execPath, [path.resolve(__dirname, '../server/dist/index.js'), '--host=127.0.0.1', `--port=${port}`, `--log-dir=${root}`, `--state-dir=${root}/state`, `--stm-config-file=${config}`, `--process-control-socket=${root}/disabled.sock`],
    { cwd: path.resolve(__dirname, '..'), env: { ...process.env, STM_ANALYSIS_STATE_FILE: '', STM_PLAYBACK_STATE_FILE: '' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let stderr = ''; child.stderr.on('data', data => stderr += data);
  t.after(async () => { if (child.exitCode === null) { child.kill('SIGTERM'); await new Promise(resolve => child.once('exit', resolve)); } await fs.rm(root, { recursive: true, force: true }); });
  const base = `http://127.0.0.1:${port}`;
  for (let i = 0; i < 150; i++) {
    assert.equal(child.exitCode, null, stderr);
    try { if ((await fetch(base + '/api/config')).ok) return { base, root, statsFile, child }; } catch {}
    await sleep(30);
  }
  assert.fail('server did not start: ' + stderr);
}

