async function failedServer(env, prelude = '') {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['-e', prelude + 'require("./server/dist/index.js")'], {
      cwd: root, env: { ...process.env, HOST: '127.0.0.1', HTTP_ACCESS_LOG: '0', STM_DIAGNOSTIC_LOG: '0', STM_CONFIG_FILE: '', STM_PLAYBACK_STATE_FILE: '', ...env },
      stdio: ['ignore', 'pipe', 'pipe']
    });
    let stdout = '', stderr = '';
    const timeout = setTimeout(() => { child.kill('SIGKILL'); reject(new Error('Startup failure did not exit: ' + stderr)); }, 10000);
    child.stdout.on('data', bytes => stdout += bytes);
    child.stderr.on('data', bytes => stderr += bytes);
    child.on('error', reject);
    child.on('close', code => { clearTimeout(timeout); resolve({ code, stdout, stderr, records: stderr.split('\n').flatMap(line => { try { return [JSON.parse(line)]; } catch { return []; } }) }); });
  });
}
