const { test } = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter, once } = require('node:events');
const { createServer } = require('node:http');
const { Duplex } = require('node:stream');
const WebSocket = require('../node_modules/ws');
const { SocketServer } = require('../server/dist/ws/socketServer');

// Exercise the real HTTP upgrade and ws framing without binding a local port.
function transportPair() {
  let client, server;
  const socket = peer => new Duplex({
    read() {},
    write(chunk, encoding, done) { peer().push(Buffer.from(chunk)); done(); },
    final(done) { peer().push(null); done(); },
    destroy(error, done) { if (!peer().destroyed) peer().push(null); done(error); }
  });
  client = socket(() => server);
  server = socket(() => client);
  return { client, server };
}

function fixture(t) {
  const http = createServer();
  const store = Object.assign(new EventEmitter(), {
    listStreams: () => [], listInterfaces: () => [], getSummary: () => ({}), tick() {}
  });
  const health = Object.assign(new EventEmitter(), { get: () => ({}) });
  const sockets = new SocketServer(http, store, health, 5000);
  sockets.start();
  const clients = [];
  t.after(async () => {
    for (const client of clients) client.terminate();
    await sockets.close(0);
  });
  const connect = () => {
    const pair = transportPair();
    let request = Buffer.alloc(0);
    const upgrade = chunk => {
      request = Buffer.concat([request, chunk]);
      const end = request.indexOf('\r\n\r\n');
      if (end < 0) return;
      pair.server.removeListener('data', upgrade);
      const [first, ...lines] = request.subarray(0, end).toString().split('\r\n');
      const [method, url] = first.split(' ');
      const headers = Object.fromEntries(lines.map(line => {
        const colon = line.indexOf(':');
        return [line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim()];
      }));
      http.emit('upgrade', { method, url, headers }, pair.server, request.subarray(end + 4));
    };
    pair.server.on('data', upgrade);
    const client = new WebSocket('ws://localhost/ws', { createConnection: () => pair.client });
    clients.push(client);
    return client;
  };
  return { sockets, store, connect };
}

test('shutdown without clients completes immediately and is repeatable', { timeout: 3000 }, async t => {
  const { sockets } = fixture(t);
  const closing = sockets.close();
  assert.equal(sockets.close(), closing);
  await closing;
  assert.equal(sockets.close(), closing);
});

test('shutdown sends going-away and completes before the grace deadline', { timeout: 3000 }, async t => {
  const { sockets, store, connect } = fixture(t);
  const client = connect();
  await once(client, 'open');
  const closed = once(client, 'close');
  // A queued stream patch must not keep the process alive for its 5-second delay.
  store.emit('streams:update');
  const started = performance.now();
  await sockets.close();
  const [code, reason] = await closed;
  assert.equal(code, 1001);
  assert.equal(reason.toString(), 'Server shutting down');
  assert.ok(performance.now() - started < 750, 'responsive client should not wait for the deadline');
});

test('shutdown terminates an unresponsive peer while closing responsive peers normally', { timeout: 3000 }, async t => {
  const { sockets, connect } = fixture(t);
  const responsive = connect(), unresponsive = connect();
  await Promise.all([once(responsive, 'open'), once(unresponsive, 'open')]);
  unresponsive.pause();
  const normalClose = once(responsive, 'close');
  const forcedClose = once(unresponsive, 'close');
  const started = performance.now();
  await sockets.close(80);
  assert.equal((await normalClose)[0], 1001);
  assert.equal((await forcedClose)[0], 1006);
  const elapsed = performance.now() - started;
  assert.ok(elapsed >= 60 && elapsed < 1000, `unresponsive peer closed after ${elapsed}ms`);
});

test('shutdown rejects new upgrades while existing peers are draining', { timeout: 3000 }, async t => {
  const { sockets, connect } = fixture(t);
  const client = connect();
  await once(client, 'open');
  client.pause();
  const closed = once(client, 'close');
  const closing = sockets.close(80);
  const late = connect();
  const error = once(late, 'error');
  let opened = false;
  late.on('open', () => { opened = true; });
  await error;
  await closing;
  await closed;
  assert.equal(opened, false);
});

