int main(int argc, char *argv[]) {
	set_trace_process("stm");
	int res = 0;

	set_signal();

	try {
		g_app = std::unique_ptr<app>(new app);

		res = g_app->run(argc, argv);
	}
	catch(std::exception &e) {
		res = 1;
		trace(0, "error: %s", e.what());
	}

	g_app.reset();

	unset_signal();

	return (res == 0) ? 0 : 1;
}

