#include <sys/inotify.h>

namespace {
enum class read_fault { none, interrupted, eof, error, overflow };
read_fault next_read_fault = read_fault::none;

void require(bool condition, const char *message) {
	if(!condition) throw std::runtime_error(message);
}

struct temporary_directory {
	std::filesystem::path path;
	temporary_directory() {
		char pattern[] = "/tmp/stm-pcap-error-XXXXXX";
		const auto created = mkdtemp(pattern);
		require(created != nullptr, "mkdtemp failed");
		path = created;
	}
	~temporary_directory() { std::error_code error; std::filesystem::remove_all(path, error); }
};

struct capture_stderr {
	FILE *file{std::tmpfile()};
	int saved{dup(STDERR_FILENO)};
	capture_stderr() {
		require(file && saved >= 0, "stderr capture failed");
		std::fflush(stderr);
		require(dup2(fileno(file), STDERR_FILENO) >= 0, "stderr redirection failed");
	}
	~capture_stderr() { std::fflush(stderr); dup2(saved, STDERR_FILENO); close(saved); std::fclose(file); }
	std::string text() {
		std::fflush(stderr);
		std::rewind(file);
		std::string result;
		char bytes[4096];
		while(const auto count = std::fread(bytes, 1, sizeof(bytes), file)) result.append(bytes, count);
		return result;
	}
};

void write_pcap(const std::filesystem::path &path) {
	const std::uint32_t words[] = {
		0x0a0d0d0a, 28, 0x1a2b3c4d, 1, 0xffffffff, 0xffffffff, 28,
		1, 20, 1, 65535, 20,
	};
	std::ofstream output(path, std::ios::binary);
	output.write(reinterpret_cast<const char *>(words), sizeof(words));
	require(output.good(), "fixture write failed");
}

void streamer_errors(const std::filesystem::path &root) {
	pcap_streamer streamer;
	std::vector<char> output;
	std::string error;
	const auto missing = root / "missing.pcapng";
	errno = EACCES;
	require(!streamer.append(missing, output, error), "missing pcap succeeded");
	require(error.find(missing.string()) != std::string::npos &&
	        error.find("stage=open errno=" + std::to_string(ENOENT)) != std::string::npos,
	        "missing pcap diagnostics lost path/open/errno");
	require(!streamer.append(root, output, error) && error.find("reason=not_regular_file") != std::string::npos,
	        "non-regular input was not diagnosed");
	const auto file = root / "valid.pcapng";
	write_pcap(file);
	next_read_fault = read_fault::interrupted;
	require(streamer.append(file, output, error), "interrupted file read was not retried");
	const auto before = output;
	next_read_fault = read_fault::eof;
	require(!streamer.append(file, output, error), "short read succeeded");
	require(error.find("stage=read errno=0") != std::string::npos &&
	        error.find("expected_bytes=48 read_bytes=0 reason=unexpected_eof") != std::string::npos,
	        "short read diagnostic differs");
	require(output == before, "failed read changed stream output");
	next_read_fault = read_fault::error;
	require(!streamer.append(file, output, error) &&
	        error.find("stage=read errno=" + std::to_string(EIO)) != std::string::npos,
	        "read error errno was lost");
	require(streamer.append(file, output, error) && output == before,
	        "read error corrupted initialized stream state");
	{ std::ofstream invalid(root / "invalid.pcapng"); invalid << "invalid"; }
	require(!streamer.append(root / "invalid.pcapng", output, error) &&
	        error.find("unsupported or invalid") != std::string::npos,
	        "pcap format error changed into a filesystem error");
}

pcap_input::config watch_config(const std::filesystem::path &dir) {
	pcap_input::config cfg;
	cfg.watch_dir = dir;
	cfg.stop_on_callback_failure = true;
	return cfg;
}

void initial_failure(const std::filesystem::path &root) {
	const auto dir = root / "initial";
	std::filesystem::create_directory(dir);
	write_pcap(dir / "cap_00001.pcapng");
	write_pcap(dir / "cap_00002.pcapng");
	auto source = pcap_input::make_source(watch_config(dir));
	source->set_callback([](const auto &) { return false; });
	require(source->run() == 1, "initial callback failure returned success");
}

void runtime_failure(const std::filesystem::path &root) {
	const auto dir = root / "runtime";
	std::filesystem::create_directory(dir);
	write_pcap(dir / "cap_00001.pcapng");
	write_pcap(dir / "cap_00002.pcapng");
	auto cfg = watch_config(dir);
	cfg.pipeline_status_file = root / "read-position.json";
	auto source = pcap_input::make_source(cfg);
	pcap_streamer streamer;
	std::string error;
	int callbacks = 0;
	source->set_callback([&](const auto &path) {
		++callbacks;
		std::ifstream status_input(cfg.pipeline_status_file);
		json status;
		status_input >> status;
		require(status["reading_file"] == path.filename().string() && status["pid"] == getpid(), "read position must publish before callback can block");
		if(callbacks > 1) require(status["last_read_file"] == "cap_00001.pcapng", "completed callback must advance read position");
		if(callbacks == 1) {
			write_pcap(dir / "cap_00003.pcapng");
			return true;
		}
		// The ring removed the file between the close notification and read.
		std::filesystem::remove(path);
		std::vector<char> output;
		return streamer.append(path, output, error);
	});
	require(source->run() == 1 && callbacks == 2, "runtime callback failure returned success");
	require(error.find("stage=open errno=" + std::to_string(ENOENT)) != std::string::npos,
	        "runtime disappearance did not retain its errno");
}

void watcher_read_failure(const std::filesystem::path &root) {
	const auto dir = root / "read-error";
	std::filesystem::create_directory(dir);
	write_pcap(dir / "cap_00001.pcapng");
	write_pcap(dir / "cap_00002.pcapng");
	auto source = pcap_input::make_source(watch_config(dir));
	source->set_callback([](const auto &) { next_read_fault = read_fault::error; return true; });
	capture_stderr capture;
	require(source->run() == 1, "inotify read error returned success");
	require(capture.text().find("inotify read failed: path=" + dir.string() + " errno=" + std::to_string(EIO)) != std::string::npos,
	        "inotify read error diagnostic differs");
}

void overflow_failure(const std::filesystem::path &root) {
	const auto dir = root / "overflow";
	std::filesystem::create_directory(dir);
	write_pcap(dir / "cap_00001.pcapng");
	write_pcap(dir / "cap_00002.pcapng");
	auto source = pcap_input::make_source(watch_config(dir));
	int callbacks = 0;
	source->set_callback([&](const auto &) {
		if(++callbacks != 1) return false;
		write_pcap(dir / "cap_00003.pcapng");
		next_read_fault = read_fault::overflow;
		return true;
	});
	require(source->run() == 1 && callbacks == 2, "overflow rescan failure returned success");
}

void ignore_signal(int) {}

void interrupted_stop(const std::filesystem::path &root, int signal, bool callback_ok) {
	const auto dir = root / ("stop-" + std::to_string(signal) + (callback_ok ? "-ok" : "-retry"));
	std::filesystem::create_directory(dir);
	write_pcap(dir / "cap_00001.pcapng");
	write_pcap(dir / "cap_00002.pcapng");
	auto cfg = watch_config(dir);
	cfg.stop_on_callback_failure = callback_ok;
	auto source = pcap_input::make_source(cfg);
	std::atomic<bool> ready{false}, done{false};
	source->set_callback([&](const auto &) { ready = true; return callback_ok; });
	struct sigaction action{}, previous{};
	action.sa_handler = ignore_signal;
	sigemptyset(&action.sa_mask);
	require(sigaction(signal, &action, &previous) == 0, "sigaction failed");
	const auto target = pthread_self();
	std::thread sender([&] {
		while(!done) {
			std::this_thread::sleep_for(std::chrono::milliseconds(10));
			if(ready && !done) pthread_kill(target, signal);
		}
	});
	const int rc = source->run();
	done = true;
	sender.join();
	sigaction(signal, &previous, nullptr);
	require(rc == 0, "interrupted stop or nonfatal callback policy changed");
}
} // namespace

extern "C" ssize_t __real_read(int, void *, std::size_t);
extern "C" ssize_t __wrap_read(int fd, void *data, std::size_t size) {
	const auto fault = next_read_fault;
	next_read_fault = read_fault::none;
	if(fault == read_fault::overflow) {
		struct inotify_event event{};
		event.mask = IN_Q_OVERFLOW;
		require(size >= sizeof(event), "overflow fixture buffer too small");
		std::memcpy(data, &event, sizeof(event));
		return sizeof(event);
	}
	if(fault == read_fault::eof) return 0;
	if(fault == read_fault::interrupted || fault == read_fault::error) {
		errno = fault == read_fault::interrupted ? EINTR : EIO;
		return -1;
	}
	return __real_read(fd, data, size);
}

int main() {
	try {
		set_trace_process("pcap-test");
		set_trace_level(0);
		temporary_directory temporary;
		streamer_errors(temporary.path);
		initial_failure(temporary.path);
		runtime_failure(temporary.path);
		watcher_read_failure(temporary.path);
		overflow_failure(temporary.path);
		interrupted_stop(temporary.path, SIGINT, true);
		interrupted_stop(temporary.path, SIGTERM, true);
		interrupted_stop(temporary.path, SIGTERM, false);
		std::puts("pcap_input_error_test: read diagnostics, initial/runtime failures and normal stops passed");
		return 0;
	}
	catch(const std::exception &error) {
		std::fprintf(stderr, "pcap_input_error_test: %s\n", error.what());
		return 1;
	}
}
