monitor::monitor(config cfg, std::unique_ptr<tsv_source> source)
	: m_cfg(std::move(cfg)),
	  m_tsv_source(std::move(source)),
	  m_reorder(m_cfg.reorder_holdback_sec) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}


	m_cfg.log.protocol_map_revision = m_protocol_map.revision();
	if(m_cfg.analysis_enabled) m_cfg.log.initial_event_time = m_cfg.analysis_from.value_or(0.0);
	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_streams = std::make_unique<stream_registry>(m_protocol_map, m_logs->events());
	netif::config interface_config;
	interface_config.collect_host_stats = !m_cfg.analysis_enabled;
	m_interfaces = std::make_unique<netif::interfaces>(std::move(interface_config), m_logs->events());
	m_pipeline_progress = std::make_unique<pipeline_progress>(pipeline_progress::config{
		.output_file = m_cfg.input.pipeline_progress_file,
		.timing_enabled = m_cfg.diagnostics_enabled && !m_cfg.analysis_enabled,
	});

	if(!m_tsv_source) {
		m_tsv_source = tsv_input::make_source(tsv_input::config{
			.mode = m_cfg.mode, .input = m_cfg.input, .tshark = m_cfg.tshark,
			.decode_as = m_protocol_map.decode_as_rules(),
			.resource_spool = m_cfg.diagnostics_enabled && !m_cfg.analysis_enabled && !m_cfg.input.pipeline_progress_file.empty()
				? m_cfg.input.pipeline_progress_file.parent_path() / "tshark-completions" : std::filesystem::path{}});
	}

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_tsv_source) {
		trace(0, "error: TSV source is not initialized");
		return 1;
	}
	m_second_boundary.reset();
	m_reorder.reset();
	m_reorder_tsv_ctx.reset();
	m_last_analysis_packet.reset();
	m_pipeline_progress->start();

	const int rc = m_tsv_source->run(*this);
	flush_reorder_all();
	if(m_cfg.analysis_enabled && m_last_analysis_packet) {
		write_second_boundary_outputs(m_last_analysis_packet->time_epoch, *m_last_analysis_packet);
	}
	m_pipeline_progress->stop();
	if(rc == 0 && m_cfg.analysis_enabled && !m_last_analysis_packet) {
		trace(0, "error: no decoded packets in the analysis time range");
		return 1;
	}
	return rc;
}

bool monitor::on_tsv_header(std::string_view header) {
	auto timing = m_pipeline_progress->timing().measure(pipeline_timing::stage::analysis);
	tsv::ctx tc;
	const std::string header_text{header};
	if(!tsv::init_ctx(tc, header_text)) {
		return false;
	}
	if(m_reorder_tsv_ctx && m_reorder_tsv_ctx->h != tc.h) {
		trace(0, "warn: tshark field layout changed; flushing the packet reorder buffer");
		flush_reorder_all();
	}
	m_reorder_tsv_ctx = std::move(tc);
	trace(7, "%.*s", static_cast<int>(header.size()), header.data());
	return true;
}

bool monitor::on_tsv_row(std::string_view row_text) {
	auto timing = m_pipeline_progress->timing().measure(pipeline_timing::stage::analysis);
	if(!m_reorder_tsv_ctx) {
		trace(0, "warn: TSV row received before header");
		return false;
	}
	m_pipeline_progress->record_tshark_packet();
	trace(7, "%.*s", static_cast<int>(row_text.size()), row_text.data());
	std::string buffered_line{row_text};
	tsv::row_t row;
	tsv::split(buffered_line, row);
	double time_epoch = 0.0;
	tsv::to_number(row[m_reorder_tsv_ctx->i.com.time_epoch], time_epoch);
	m_reorder.push(time_epoch, std::move(buffered_line));
	flush_reorder_ready();
	return true;
}

void monitor::on_tsv_end() {
}

void monitor::on_tsv_read_begin() {
	m_pipeline_progress->timing().begin(pipeline_timing::stage::tsv_read);
}

