#include "thread_base.h"
// #include "debug.h"
#include <linux/sched.h>
#include <sys/syscall.h>
#include <sys/resource.h>
#include <asm/types.h>

#ifndef SCHED_DEADLINE
#define SCHED_DEADLINE	6
#endif

#ifdef __x86_64__
#define __NR_sched_setattr		314
#define __NR_sched_getattr		315
#endif

#ifdef __i386__
#define __NR_sched_setattr		351
#define __NR_sched_getattr		352
#endif

struct sched_attr {
	__u32 size;

	__u32 sched_policy;
	__u64 sched_flags;

	/* SCHED_NORMAL, SCHED_BATCH */
	__s32 sched_nice;

	/* SCHED_FIFO, SCHED_RR */
	__u32 sched_priority;

	/* SCHED_DEADLINE (nsec) */
	__u64 sched_runtime;
	__u64 sched_deadline;
	__u64 sched_period;
};

extern "C" {
int sched_setattr(pid_t pid, const struct sched_attr *attr, unsigned int flags)
{
#if defined(__i386__) || defined(__x86_64__)
	return syscall(__NR_sched_setattr, pid, attr, flags);
#else
	return -1;
#endif
}

int sched_getattr(pid_t pid, struct sched_attr *attr, unsigned int size, unsigned int flags)
{
#if defined(__i386__) || defined(__x86_64__)
	return syscall(__NR_sched_getattr, pid, attr, size, flags);
#else
	return -1;
#endif
}
};

///////////////////////////////////////////////////////////////////////////////
// コンストラクタ
//
thread_base::thread_base()
	: m_abort(false)
	, m_running(false)
{
}

///////////////////////////////////////////////////////////////////////////////
// デストラクタ
//
thread_base::~thread_base()
{
}

///////////////////////////////////////////////////////////////////////////////
// スレッド終了待ち
//
void thread_base::wait_for_terminate()
{
	if (m_worker.joinable()) {
		m_worker.join();
	}
}

///////////////////////////////////////////////////////////////////////////////
// スレッドのプライオリティを変更する(SCHED_FIFO/RR)
//
bool thread_base::set_priority(int priority, int policy)
{
	pthread_attr_t	attr;
	sched_param		sched_param;
	int				rc;

	// 上下限チェック
	int	limit = ::sched_get_priority_min(policy);
	if (priority < limit) {
		priority = limit;
	}
	limit = ::sched_get_priority_max(policy);
	if (priority > limit) {
		priority = limit;
	}

	// ulimit値チェックと変更
	rlimit	rlim;
	bool	do_set = false;
	::getrlimit(RLIMIT_RTPRIO, &rlim);
	// TRACE(3, ("rtprio cur=%lu max=%lu\n", rlim.rlim_cur, rlim.rlim_max));
	if (rlim.rlim_max < static_cast<unsigned long>(limit)) {
		rlim.rlim_max = limit;
		do_set = true;
	}
	if (rlim.rlim_cur < static_cast<unsigned long>(limit)) {
		rlim.rlim_cur = limit;
		do_set = true;
	}
	if (do_set) {
		rc = ::setrlimit(RLIMIT_RTPRIO, &rlim);
		if (rc != 0) {
			::perror("setrlimit");
		}
	}

	// プライオリティ・スケジュール変更
	::pthread_attr_init(&attr);
	::pthread_attr_setschedpolicy(&attr, policy);
	sched_param.sched_priority = priority;
	::pthread_attr_setschedparam(&attr, &sched_param);
	if (::pthread_setschedparam(m_worker.native_handle(), policy, &sched_param) != 0) {
		::perror("pthread_setschedparam");
		return false;
	}

	int	get_policy;
	if (::pthread_getschedparam(m_worker.native_handle(), &get_policy, &sched_param) == 0) {
		if (policy != get_policy) {
			::printf("Can't set schedule policy\n");
			return false;
		} else if (sched_param.sched_priority != priority) {
			::printf("Can't set priority, now priority is %d\n", sched_param.sched_priority);
			return false;
		}
	} else {
		::perror("pthread_getschedparam");
	}

	return true;
}

///////////////////////////////////////////////////////////////////////////////
// スレッドをSCHED_DEADLINEに変更する
//
bool thread_base::set_deadline(uint64_t runtime, uint64_t deadline, uint64_t period)
{
#ifdef SCHED_DEADLINE
	sched_attr	attr;

	attr.size			= sizeof(attr);
	attr.sched_flags	= 0;
	attr.sched_nice		= 0;
	attr.sched_priority = 0;

	attr.sched_policy	= SCHED_DEADLINE;
	attr.sched_runtime	= runtime;
	attr.sched_deadline	= deadline;
	attr.sched_period	= period;

	if (::sched_setattr(0, &attr, 0) < 0) {
		::perror("sched_setattr");
		return false;
	}

	return true;
#else
	return false;
#endif
}
