namespace data_storage {
inline std::filesystem::path lock_path;
inline bool managed = false;
inline thread_local unsigned depth = 0;

inline void configure(const std::filesystem::path &file, const std::filesystem::path &override_root = {}) {
    if(file.empty()) return;
