    lock_path = root / "runtime" / "storage.lock";
}

class guard {
    int fd_ = -1;
    bool entered_ = false;
public:
    guard() {
        if(!managed) return;
        if(depth == 0) {
            fd_ = ::open(lock_path.c_str(), O_CREAT | O_RDWR | O_CLOEXEC | O_NOFOLLOW, 0600);
            if(fd_ < 0) throw std::system_error(errno, std::generic_category(), "open storage lock");
            if(::flock(fd_, LOCK_SH) != 0) {
                const int error = errno;
                ::close(fd_);
                throw std::system_error(error, std::generic_category(), "lock storage");
            }
        }
