	if(m_directory.empty()) return;
	m_input = input;
	m_started_at = epoch();
	m_started = std::chrono::steady_clock::now();
	++m_sequence;
}

pid_t tshark_resources::wait(pid_t pid, int *status, int options) {
	rusage usage{};
	pid_t result;
	do { result = wait4(pid, status, options, &usage); } while(result < 0 && errno == EINTR);
	if(result <= 0 || m_directory.empty()) return result;
	const auto ended = epoch();
	const auto elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - m_started).count();
	const auto identity = m_session + "-" + std::to_string(m_sequence);
	const json record{{"schema_version", 1}, {"record_type", "tshark_completion"}, {"identity", identity},
		{"pid", result}, {"stm_pid", getpid()}, {"mode", m_mode}, {"input_file", m_input.empty() ? json(nullptr) : json(m_input.string())},
		{"started_at", m_started_at}, {"ended_at", ended}, {"elapsed_sec", elapsed},
		{"user_cpu_sec", seconds(usage.ru_utime)}, {"system_cpu_sec", seconds(usage.ru_stime)},
		{"max_rss_bytes", static_cast<unsigned long long>(usage.ru_maxrss) * 1024},
		{"exit_code", WIFEXITED(*status) ? json(WEXITSTATUS(*status)) : json(nullptr)},
		{"signal", WIFSIGNALED(*status) ? json(WTERMSIG(*status)) : json(nullptr)}};
	// Each immutable, newline-terminated spool file is one append-only event.
	// FE acknowledges it only after copying it into the diagnostic archive.
	int fd = -1;
	std::filesystem::path temporary;
	try {
		std::filesystem::create_directories(m_directory);
		if(std::filesystem::is_symlink(std::filesystem::symlink_status(m_directory))) throw std::runtime_error("spool is a symlink");
		const auto target = m_directory / ("tshark-" + identity + ".ndjson");
		temporary = target.string() + ".tmp";
		fd = open(temporary.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC | O_NOFOLLOW, 0644);
		if(fd < 0) throw std::runtime_error("cannot create completion record");
		auto line = record.dump() + "\n";
		std::size_t offset = 0;
		while(offset < line.size()) {
			const auto n = write(fd, line.data() + offset, line.size() - offset);
			if(n < 0 && errno == EINTR) continue;
			if(n <= 0) throw std::runtime_error("cannot write completion record");
			offset += n;
		}
		const int closed = close(fd); fd = -1;
		if(closed != 0) throw std::runtime_error("cannot close completion record");
		// Exclusive publication never overwrites a previously recorded event.
		std::filesystem::create_hard_link(temporary, target);
		std::filesystem::remove(temporary);
	} catch(const std::exception &error) {
		if(fd >= 0) close(fd);
		std::error_code ignored;
		if(!temporary.empty()) std::filesystem::remove(temporary, ignored);
		trace(0, "warn: failed to save tshark completion: %s", error.what());
	}
	return result;
}
