		input_valid = true;
		recover();
		update(std::move(next), "configuration_updated");
	}
	void run() {
		for(;;) {
			try { refresh(); }
			catch(const std::exception &error) {
				const std::string message = std::string(error.what()).substr(0, 256);
				if(message != last_error) trace_notice("log-level target=%s configuration rejected: %s", process.c_str(), message.c_str());
